const store = $getWorkflowStaticData('global');
store.paused = store.paused || {};
const PAUSE_HOURS = 2;
const now = Date.now();

function pause(...chats) {
  for (const c of chats) if (c) store.paused[c] = now + PAUSE_HOURS * 3600 * 1000;
}
function isPaused(...chats) {
  return chats.some(c => c && store.paused[c] && store.paused[c] > now);
}

const body = $input.first().json.body;
const event = body.event;
const list = Array.isArray(body.data) ? body.data : [body.data];

// 1) Sir Imran READ (seen) a message
if (event === 'messages.update') {
  for (const u of list) {
    if (!u) continue;
    const fromMe = u.fromMe ?? (u.key && u.key.fromMe);
    const chat = u.remoteJid ?? (u.key && u.key.remoteJid);
    if (fromMe === false && String(u.status).toUpperCase() === 'READ') pause(chat);
  }
  return [];
}

// 2) A new message
if (event === 'messages.upsert') {
  const d = list[0];
  const chat = d.key.remoteJid;
  const chatAlt = d.key.remoteJidAlt;

  // skip groups and status updates
  if (chat === 'status@broadcast' || chat.endsWith('@g.us')) return [];

  // Sir Imran wrote himself -> bot goes quiet
  if (d.key.fromMe) { pause(chat, chatAlt); return []; }

  // Sir Imran is handling this chat -> bot stays quiet
  if (isPaused(chat, chatAlt)) return [];

  const m = d.message || {};
  const text = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || '';
  if (!text) return [];

  return [{ json: { ...$input.first().json, text } }];
}

return [];
